import { useState, useEffect } from "react";
import CompanyLayout from "./CompanyLayout";
import axios from "axios";

// تعريف حالات الطلبات والألوان المتوافقة مع CSS الخاص بك
const STATUS = {
  pending:  { badge: "badge-orange", label: "Pending"  },
  accepted: { badge: "badge-green",  label: "Accepted" },
  rejected: { badge: "badge-red",    label: "Rejected" },
};

export default function CompanyDashboard() {
  const [active, setActive] = useState("dashboard");
  const [loading, setLoading] = useState(true);
  
  // حالات البيانات القادمة من Django
  const [companyInfo, setCompanyInfo] = useState(null);
  const [recentApplicants, setRecentApplicants] = useState([]);
  const [offerStats, setOfferStats] = useState([]);
  const [accountStatus, setAccountStatus] = useState("pending");
  const [stats, setStats] = useState({
    active_offers: 0,
    total_applicants: 0,
    pending_review: 0,
    accepted_interns: 0
  });

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const token = localStorage.getItem("token");
        // تصحيح صياغة التوكن لضمان جلب البيانات
        const headers = { Authorization:` Bearer ${token} `};

        // جلب الإحصائيات من الـ API الذي أنشأناه
        const res = await axios.get("http://127.0.0.1:8000/api/company/dashboard-stats/", { headers });
        
        setCompanyInfo(res.data.company);
        setRecentApplicants(res.data.recent_applicants || []);
        setOfferStats(res.data.offers || []);
        setStats(res.data.stats || stats);
        setAccountStatus(res.data.company.status || "pending");
        
        setLoading(false);
      } catch (err) {
        console.error("Error fetching dashboard data:", err);
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  // شاشة التحميل لمنع ظهور أخطاء undefined أثناء جلب البيانات
  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 font-syne">
       <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-slate-500">جاري تحميل لوحة التحكم...</p>
       </div>
    </div>
  );

  return (
    <CompanyLayout active={active} onNav={setActive} pendingCount={stats.pending_review}>
      <div className="p-5 md:p-8 max-w-5xl mx-auto">

        {/* ── بنرات حالة الحساب ── */}
        {accountStatus === "pending" && (
          <div className="mb-6 bg-cream/60 border border-cream rounded-2xl p-5 flex gap-4 items-start anim-fade-up">
            <div className="text-3xl shrink-0">⏳</div>
            <div className="flex-1">
              <h3 className="font-syne font-bold text-slate-800 text-base mb-1">Account pending validation</h3>
              <p className="text-sm text-slate-600 font-light leading-relaxed">
                Your registration is under review by the university administration.
              </p>
            </div>
          </div>
        )}

        {accountStatus !== "approved" ? (
          <div className="card border border-slate-200 p-10 text-center anim-fade-up">
            <div className="text-5xl mb-4">{accountStatus === "pending" ? "🔒" : "🚫"}</div>
            <h3 className="font-syne font-bold text-slate-700 text-xl mb-2">
              {accountStatus === "pending" ? "Platform locked" : "Access denied"}
            </h3>
            <p className="text-slate-400 text-sm">الحساب بانتظار تفعيل المسؤولين لتتمكن من إضافة العروض.</p>
          </div>
        ) : (
          <div className="anim-fade-up">
            {/* Header */}
            <div className="mb-7">
              <div className="flex items-start justify-between flex-wrap gap-3">
                <div>
                  <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Overview</p>
                  </div>
                <div className="space-y-3">
                  {offerStats.length > 0 ? offerStats.map((o, i) => (
                    <div key={i} className="card border border-slate-200 p-4 bg-white rounded-xl">
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="font-syne font-bold text-slate-800 text-sm">{o.title}</div>
                        <span className={`badge shrink-0 ${o.active ? "badge-green" : "badge-slate"}`}>
                          {o.active ? "Active" : "Closed"}
                        </span>
                      </div>
                      <div className="flex justify-between items-center text-xs text-slate-400">
                        <span>👥 {o.applicants_count} applicants</span>
                        <span>📅 {o.created_at}</span>
                      </div>
                    </div>
                  )) : <p className="p-5 text-center text-sm text-slate-400 card border-dashed border-slate-200">No offers posted.</p>}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </CompanyLayout>
  );
}
